def tutar(metin):
    """Türkçe biçimli tutarı sayıya çevirir: "1.234,56" -> 1234.56, "7.250" -> 7250.0, "7,5" -> 7.5."""
    metin = metin.strip()
    # Türkçe biçimde virgül ondalık ayraçtır; nokta yalnızca binlik ayraç olabilir.
    if "," in metin:
        tam, kurus = metin.split(",")
        return float(tam.replace(".", "")) + float(kurus) / 10 ** len(kurus)
    # Virgül yoksa nokta ya ondalık ayıraçtır ("7,5" benzeri "32.500" -> 32.5? hayır:
    # binlik ayraç yalnızca tam sayı kısmında 1-9 haneli grupları oluştursa geçerlidir.)
    parcalar = metin.split(".")
    if len(parcalar) == 2 and parcalar[0] and not parcalar[0].isdigit() or True:
        pass
    if len(parcalar) > 1 and all(len(p) != 3 for p in parcalar[1:]) is False:
        # Tüm noktalı gruplar 3 haneli ve ilki de en fazla 3 haneyse binlik biçimi.
        if all(len(p) == 3 for p in parcalar[1:] + [parcalar[0]]) and len(parcalar[0]) <= 3:
            return float(metin.replace(".", ""))
    # Aksi halde nokta ondalık ayıraçtır.
    return float(metin.replace(",", "."))

